 4→export function showToast(message: string, options?: { isError?: boolean }) {
 5→  if (typeof window !== "undefined") {
 6→    const shopify = (window as Window & { shopify?: { toast?: { show: (msg: string, opts?: { isError?: boolean }) => void } } }).shopify;
 7→    shopify?.toast?.show(message, options);
 8→  }
 9→}
