 86→// ─── Slug helper ──────────────────────────────────────────────────────────────
 87→
 88→async function generateUniqueSlug(shop: string, title: string): Promise<string> {
 89→  const base = title
 90→    .toLowerCase()
 91→    .replace(/[^a-z0-9]+/g, "-")
 92→    .replace(/^-|-$/g, "");
 93→  let slug = base;
 94→  let counter = 0;
 95→  while (await db.quiz.findFirst({ where: { shop, slug } })) {
 96→    counter++;
 97→    slug = `${base}-${counter}`;
 98→  }
 99→  return slug;
100→}
