102→// ─── Loader ───────────────────────────────────────────────────────────────────
103→
104→export async function loader({ request }: LoaderFunctionArgs) {
105→  const { session } = await authenticate.admin(request);
106→
107→  try {
108→    const [customTemplates, globalTemplates] = await Promise.all([
109→      db.quizTemplate.findMany({
110→        where: { shop: session.shop, isGlobal: false },
111→        orderBy: { createdAt: "desc" },
112→      }),
113→      db.quizTemplate.findMany({
114→        where: { isGlobal: true },
115→        orderBy: { usageCount: "desc" },
116→      }),
117→    ]);
118→
119→    return { customTemplates, globalTemplates };
120→  } catch (error) {
121→    console.error("Templates loader error:", error);
122→    return { customTemplates: [], globalTemplates: [] };
123→  }
124→}
