126→// ─── Action ───────────────────────────────────────────────────────────────────
127→
128→export async function action({ request }: ActionFunctionArgs) {
129→  const { session } = await authenticate.admin(request);
130→  const formData = await request.formData();
131→  const intent = formData.get("intent") as string;
132→
133→  if (intent === "use-template") {
134→    const templateId = formData.get("templateId") as string;
135→
136→    try {
137→      const template = await db.quizTemplate.findFirst({
138→        where: { id: templateId },
139→      });
140→      if (!template) {
141→        return data({ error: "Template not found" }, { status: 404 });
142→      }
143→
144→      await db.quizTemplate.update({
145→        where: { id: templateId },
146→        data: { usageCount: { increment: 1 } },
147→      });
148→
149→      const slug = await generateUniqueSlug(session.shop, template.name);
150→      const quiz = await db.quiz.create({
151→        data: {
152→          shop: session.shop,
153→          title: template.name,
154→          slug,
155→          type: "product-recommendation",
156→          status: "draft",
157→        },
158→      });
159→
160→      return redirect(`/app/quizzes/${quiz.id}`);
161→    } catch (error) {
162→      console.error("use-template action error:", error);
163→      return data({ error: "Failed to create quiz from template" }, { status: 500 });
164→    }
165→  }
166→
167→  return data({ error: "Unknown intent" }, { status: 400 });
168→}
