272→function PlanGateBanner({
273→  requiredPlan,
274→  currentPlan,
275→}: {
276→  requiredPlan: string;
277→  currentPlan: string;
278→}) {
279→  const planOrder = ["free", "starter", "pro", "enterprise"];
280→  const isGated =
281→    planOrder.indexOf(currentPlan) < planOrder.indexOf(requiredPlan);
282→
283→  if (!isGated) return null;
284→
285→  const label = requiredPlan.charAt(0).toUpperCase() + requiredPlan.slice(1);
286→
287→  return (
288→    <Banner
289→      tone="warning"
290→      title={`${label} plan required`}
291→      action={{ content: "Upgrade now", url: "/app/billing" }}
292→    >
293→      <p>
294→        Upgrade to the {label} plan or higher to use this integration.
295→      </p>
296→    </Banner>
297→  );
298→}
