157→// ─── Action ───────────────────────────────────────────────────────────────────
158→
159→export const action = async ({ request }: ActionFunctionArgs) => {
160→  const { session } = await authenticate.admin(request);
161→  const formData = await request.formData();
162→  const intent = String(formData.get("intent") ?? "");
163→
164→  try {
165→    if (intent !== "save") {
166→      return data({ error: "Unknown action" }, { status: 400 });
167→    }
168→
169→    const position = String(formData.get("position") ?? "embedded");
170→    const triggerType = String(formData.get("triggerType") ?? "button");
171→
172→    // Build triggerValue based on type
173→    const triggerValue: TriggerValue = {};
174→    if (triggerType === "scroll") {
175→      const depth = String(formData.get("scrollDepth") ?? "").trim();
176→      if (depth) triggerValue.scrollDepth = depth;
177→    } else if (triggerType === "timer") {
178→      const delay = String(formData.get("delaySeconds") ?? "").trim();
179→      if (delay) triggerValue.delaySeconds = delay;
180→    }
181→
182→    const primaryColor = String(formData.get("primaryColor") ?? "#5C6AC4").trim() || "#5C6AC4";
183→    const borderRadius = String(formData.get("borderRadius") ?? "8").trim() || "8";
184→    const fontSize = String(formData.get("fontSize") ?? "16").trim() || "16";
185→    const showPoweredBy = formData.get("showPoweredBy") === "true";
186→    const logoUrl = String(formData.get("logoUrl") ?? "").trim() || undefined;
187→    const customCssRaw = String(formData.get("customCss") ?? "").trim();
188→
189→    const updates = {
190→      position,
191→      triggerType,
192→      triggerValue: JSON.stringify(triggerValue),
193→      styling: JSON.stringify({ primaryColor, borderRadius, fontSize }),
194→      branding: JSON.stringify({ showPoweredBy, ...(logoUrl ? { logoUrl } : {}) }),
195→      customCss: customCssRaw || null,
196→      updatedAt: new Date(),
197→    };
198→
199→    await db.widgetConfig.upsert({
200→      where: { shop: session.shop },
201→      create: { shop: session.shop, ...updates },
202→      update: updates,
203→    });
204→
205→    return { success: true, message: "Widget settings saved." };
206→  } catch (error) {
207→    if (error instanceof Response) throw error;
208→    console.error("Widget action failed:", error);
209→    return data({ error: "Failed to save widget settings." }, { status: 500 });
210→  }
211→};
