118→// ─── Loader ───────────────────────────────────────────────────────────────────
119→
120→export const loader = async ({ request, params }: LoaderFunctionArgs) => {
121→  const { session } = await authenticate.admin(request);
122→  const quizId = params.id;
123→
124→  if (!quizId) {
125→    throw data({ error: "Missing quiz ID" }, { status: 400 });
126→  }
127→
128→  try {
129→    const quiz = await db.quiz.findFirst({
130→      where: { id: quizId, shop: session.shop },
131→      include: {
132→        resultPages: { orderBy: { position: "asc" } },
133→      },
134→    });
135→
136→    if (!quiz) {
137→      throw data({ error: "Quiz not found" }, { status: 404 });
138→    }
139→
140→    const resultPages: ResultPageData[] = quiz.resultPages.map((r) => ({
141→      id: r.id,
142→      quizId: r.quizId,
143→      title: r.title,
144→      description: r.description,
145→      type: r.type,
146→      minScore: r.minScore,
147→      maxScore: r.maxScore,
148→      matchTags: parseSafe<string[]>(r.matchTags, []),
149→      productLimit: r.productLimit,
150→      layout: r.layout,
151→      showDiscount: r.showDiscount,
152→      discountType: r.discountType,
153→      discountValue: r.discountValue,
154→      discountCode: r.discountCode,
155→      ctaText: r.ctaText,
156→      ctaUrl: r.ctaUrl,
157→      styling: parseSafe<Record<string, unknown>>(r.styling, {}),
158→      position: r.position,
159→      createdAt: r.createdAt.toISOString(),
160→      updatedAt: r.updatedAt.toISOString(),
161→    }));
162→
163→    return {
164→      quiz: {
165→        id: quiz.id,
166→        title: quiz.title,
167→        status: quiz.status,
168→      },
169→      resultPages,
170→    } as LoaderData;
171→  } catch (error) {
172→    if (error instanceof Response) throw error;
173→    throw data({ error: "Failed to load result pages" }, { status: 500 });
174→  }
175→};
