668→
669→  // Toast from page-level action (create / delete / reorder)
670→  useEffect(() => {
671→    if (!actionData) return;
672→    if ("success" in actionData && actionData.success && "message" in actionData) {
673→      showToast(String(actionData.message), { duration: 3000 });
674→    } else if ("error" in actionData && actionData.error) {
675→      showToast(String(actionData.error), { duration: 4000, isError: true });
676→    }
677→  }, [actionData]);
678→
679→  // Auto-select first page after new creation (resultPages re-loads via loader)
680→  useEffect(() => {
681→    if (resultPages.length > 0 && !selectedPageId) {
682→      setSelectedPageId(resultPages[0].id);
