) {
  if (typeof window !== "undefined") {
    const shopify = (
      window as Window & {
        shopify?: {
          toast?: {
            show: (
              msg: string,
              opts?: { isError?: boolean; duration?: number },
            ) => void;
          };
        };
      }
    ).shopify;
    shopify?.toast?.show(message, options);
  }
}

