export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);

  try {
    const sub = await db.subscription.findUnique({
      where: { shop: session.shop },
      select: { planId: true },
    });
    return { currentPlan: sub?.planId ?? "free" };
  } catch {
    return { currentPlan: "free" };
  }
};

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = String(formData.get("intent") ?? "");

  try {
    if (intent === "save-general") {
      // Persist general settings to WidgetConfig.branding (reuse existing singleton)
      const showBranding = formData.get("showBranding") === "true";
      const defaultLanguage = String(formData.get("defaultLanguage") ?? "en");
      const attributionWindow = String(
        formData.get("attributionWindow") ?? "7",
      );
      const tagPrefix = String(formData.get("tagPrefix") ?? "qs-");

      await db.widgetConfig.upsert({
        where: { shop: session.shop },
        create: {
          shop: session.shop,
          branding: JSON.stringify({ showPoweredBy: showBranding }),
          settings: JSON.stringify({ defaultLanguage, attributionWindow, tagPrefix }),
        },
        update: {
          branding: JSON.stringify({ showPoweredBy: showBranding }),
          settings: JSON.stringify({ defaultLanguage, attributionWindow, tagPrefix }),
        },
      });
      return { success: true, message: "General settings saved." };
    }

    if (intent === "save-email") {
      const collectEmails = formData.get("collectEmails") === "true";
      const emailHeadline = String(formData.get("emailHeadline") ?? "").trim();
      const gdprConsentText = String(
        formData.get("gdprConsentText") ?? "",
      ).trim();
      const skipLinkText = String(formData.get("skipLinkText") ?? "").trim();
      const discountCode = String(formData.get("discountCode") ?? "").trim();

      await db.widgetConfig.upsert({
        where: { shop: session.shop },
        create: {
          shop: session.shop,
          settings: JSON.stringify({
            collectEmails,
            emailHeadline,
            gdprConsentText,
            skipLinkText,
            discountCode,
          }),
        },
        update: {
          settings: JSON.stringify({
            collectEmails,
            emailHeadline,
            gdprConsentText,
            skipLinkText,
            discountCode,
          }),
        },
      });
      return { success: true, message: "Email capture settings saved." };
    }

    return { error: "Unknown intent" };
  } catch (error) {
    console.error("Settings action error:", error);
    return { error: "Failed to save settings. Please try again." };
  }
};

